	__models__GongNoteShape__00000005_.IsExpanded = false
	__models__GongNoteShape__00000006_.Name = `07. Aerial Refuelling-Note07AerialRefuelling`
	__models__GongNoteShape__00000006_.Identifier = `ref_models.Note07AerialRefuelling`
	__models__GongNoteShape__00000006_.Body = `07. Aerial Refuelling Story

[models.AerialRefuellingTimeSliceType] describes military air-to-air refuelling tracks ([models.AerialRefuellingTrackType])
and racetrack anchors ([models.AerialRefuellingAnchorType]) composed of ordered [models.AerialRefuellingPointType] waypoints and [models.AuthorityForAerialRefuellingType].
`
	__models__GongNoteShape__00000006_.BodyHTML = `<p>07. Aerial Refuelling Story
<p><a href="/models#AerialRefuellingTimeSliceType">models.AerialRefuellingTimeSliceType</a> describes military air-to-air refuelling tracks (<a href="/models#AerialRefuellingTrackType">models.AerialRefuellingTrackType</a>)
and racetrack anchors (<a href="/models#AerialRefuellingAnchorType">models.AerialRefuellingAnchorType</a>) composed of ordered <a href="/models#AerialRefuellingPointType">models.AerialRefuellingPointType</a> waypoints and <a href="/models#AuthorityForAerialRefuellingType">models.AuthorityForAerialRefuellingType</a>.
`
